#!/usr/bin/env node
// Generated by claude-kit. PreToolUse guardrail for Edit / Write / MultiEdit / NotebookEdit.
// Blocks edits to protected paths (lockfiles, build output, secrets, committed migrations) and
// added code that breaks a content rule, and tells Claude why so it fixes the cause instead.
// Regenerated by `claude-kit sync`: change rules in .claude-kit/config.json, not here.
'use strict';

const { existsSync, readFileSync } = require('node:fs');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

/** gitignore-style patterns. `committedOnly` rules skip files git doesn't track yet. */
const RULES = [
  {
    pattern: 'package-lock.json',
    reason:
      'lockfiles are generated by the package manager; change package.json and reinstall instead',
  },
  {
    pattern: 'pnpm-lock.yaml',
    reason:
      'lockfiles are generated by the package manager; change package.json and reinstall instead',
  },
  {
    pattern: 'yarn.lock',
    reason:
      'lockfiles are generated by the package manager; change package.json and reinstall instead',
  },
  {
    pattern: 'bun.lock',
    reason:
      'lockfiles are generated by the package manager; change package.json and reinstall instead',
  },
  {
    pattern: 'bun.lockb',
    reason:
      'lockfiles are generated by the package manager; change package.json and reinstall instead',
  },
  {
    pattern: 'node_modules/',
    reason: 'dependencies are installed, not edited; patch via the package manager',
  },
  {
    pattern: 'dist/',
    reason: 'build output is generated; edit the sources instead',
  },
  {
    pattern: '.env',
    reason: 'secrets file; edit it yourself, never through Claude',
  },
  {
    pattern: '.env.*',
    reason: 'secrets file; edit it yourself, never through Claude',
  },
  {
    pattern: '.git/',
    reason: 'git internals; use git commands instead',
  },
];

/** File names that are never blocked, even if a rule matches. */
const EXCEPTIONS = ['.env.example', '.env.sample', '.env.template'];

/** Checks on added text (opt-in via guardrails.content in .claude-kit/config.json). */
const CONTENT_RULES = [];

function escape(ch) {
  return /[.+^${}()|\\]/.test(ch) ? '\\' + ch : ch;
}

function toRegExp(pattern) {
  const dirOnly = pattern.endsWith('/');
  let p = pattern.replace(/\/+$/, '');
  const anchored = p.startsWith('/') || p.includes('/');
  p = p.replace(/^\//, '');
  let re = '';
  for (let i = 0; i < p.length; i++) {
    const ch = p[i];
    if (ch === '*' && p[i + 1] === '*') {
      if (p[i + 2] === '/') {
        re += '(?:.*/)?';
        i += 2;
      } else {
        re += '.*';
        i += 1;
      }
    } else if (ch === '*') re += '[^/]*';
    else if (ch === '?') re += '[^/]';
    else if (ch === '[') {
      const end = p.indexOf(']', i);
      if (end === -1) re += '\\[';
      else {
        re += p.slice(i, end + 1);
        i = end;
      }
    } else re += escape(ch);
  }
  return new RegExp((anchored ? '^' : '(?:^|/)') + re + (dirOnly ? '/' : '(?:/|$)'));
}

function matchesAny(patterns, rel) {
  return patterns.some((p) => toRegExp(p).test(rel));
}

/** Tracked by git; without git, any existing file counts as committed. */
function isCommitted(root, rel) {
  const res = spawnSync('git', ['ls-files', '--error-unmatch', '--', rel], {
    cwd: root,
    stdio: 'ignore',
  });
  if (res.error || res.status === 128) return existsSync(path.join(root, rel));
  return res.status === 0;
}

function count(re, text) {
  if (typeof text !== 'string' || !text) return 0;
  re.lastIndex = 0;
  let n = 0;
  while (re.exec(text)) {
    n++;
    if (re.lastIndex === 0) break;
  }
  return n;
}

/** [before, after] text of the edit, so only matches Claude *adds* are blocked. */
function editTexts(toolName, toolInput, abs) {
  if (toolName === 'Write') {
    let before = '';
    try {
      before = readFileSync(abs, 'utf8');
    } catch {
      // new file
    }
    return [[before, toolInput.content]];
  }
  if (Array.isArray(toolInput.edits))
    return toolInput.edits.map((e) => [e.old_string, e.new_string]);
  if (typeof toolInput.new_string === 'string')
    return [[toolInput.old_string, toolInput.new_string]];
  return [];
}

/** Expands {dir} {name} {ext} {path} {subdir} {subpath} for a project-relative file. */
function testCandidates(templates, rel) {
  const dir = path.posix.dirname(rel) === '.' ? '' : path.posix.dirname(rel);
  const ext = path.posix.extname(rel).slice(1);
  const name = path.posix.basename(rel, ext ? '.' + ext : '');
  const noExt = dir ? `${dir}/${name}` : name;
  const strip = (p) => p.replace(/^(?:src|lib|app)(?:\/|$)/, '');
  const vars = { dir, name, ext, path: noExt, subdir: strip(dir), subpath: strip(noExt) };
  const out = templates.map((t) =>
    t
      .replace(/\{(\w+)\}/g, (m, k) => (k in vars ? vars[k] : m))
      .replace(/\/{2,}/g, '/')
      .replace(/^\//, ''),
  );
  return [...new Set(out)];
}

function block(message) {
  process.stderr.write(`claude-kit guardrail: ${message}\n`);
  return 2;
}

function main() {
  let input;
  try {
    input = JSON.parse(readFileSync(0, 'utf8'));
  } catch {
    return 0; // never block on input we don't understand
  }
  const toolInput = input.tool_input || {};
  const target = toolInput.file_path || toolInput.notebook_path;
  if (typeof target !== 'string' || !target) return 0;

  const root = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  const abs = path.resolve(input.cwd || root, target);
  const rel = path.relative(root, abs).split(path.sep).join('/');
  if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) return 0; // outside the project: Claude Code's own permissions apply
  if (EXCEPTIONS.includes(path.posix.basename(rel))) return 0;

  for (const rule of RULES) {
    if (!toRegExp(rule.pattern).test(rel)) continue;
    if (rule.committedOnly && !isCommitted(root, rel)) continue;
    return block(
      `editing ${rel} is blocked (${rule.pattern}): ${rule.reason}. ` +
        'If this edit is really needed, ask the user to make it or to adjust the guardrails.',
    );
  }

  const texts = editTexts(input.tool_name, toolInput, abs);
  for (const rule of CONTENT_RULES) {
    if (!matchesAny(rule.files, rel) || matchesAny(rule.exclude, rel)) continue;
    const re = new RegExp(rule.pattern, 'gm');
    const added = texts.reduce((n, [before, after]) => n + count(re, after) - count(re, before), 0);
    if (added <= 0) continue;
    if (rule.tests) {
      const candidates = testCandidates(rule.tests, rel);
      if (candidates.some((t) => existsSync(path.join(root, t)))) continue;
      return block(
        `this edit to ${rel} breaks "${rule.id}": ${rule.reason}. ` +
          `No test file found; create one of: ${candidates.join(', ')}, then retry the edit.`,
      );
    }
    return block(
      `this edit to ${rel} adds code that breaks "${rule.id}": ${rule.reason}. ` +
        "Rewrite the change without it; if it's really needed, ask the user (rules live in .claude-kit/config.json).",
    );
  }
  return 0;
}

process.exit(main());
